<?php require 'config.php';require_login();if(empty($_SESSION['cart'])){header('Location: cart.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$ids=array_keys($_SESSION['cart']);$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM cakes WHERE id IN ($marks)");$s->execute($ids);$cakes=$s->fetchAll();$total=0;foreach($cakes as $c){$q=$_SESSION['cart'][$c['id']]['quantity'];if($q>$c['stock'])exit('Stock changed. Please update your cart.');$total+=$c['price']*$q;}$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO orders(user_id,total,shipping_name,phone,address,city,postal_code,delivery_note) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$_SESSION['user_id'],$total,trim($_POST['shipping_name']),trim($_POST['phone']),trim($_POST['address']),trim($_POST['city']),trim($_POST['postal_code']),trim($_POST['delivery_note'])]);$oid=$pdo->lastInsertId();foreach($cakes as $c){$x=$_SESSION['cart'][$c['id']];$pdo->prepare('INSERT INTO order_items(order_id,cake_id,cake_name,quantity,unit_price,cake_size,message_text) VALUES(?,?,?,?,?,?,?)')->execute([$oid,$c['id'],$c['name'],$x['quantity'],$c['price'],$x['size'],$x['message_text']]);$pdo->prepare('UPDATE cakes SET stock=stock-? WHERE id=?')->execute([$x['quantity'],$c['id']]);}$pdo->commit();$_SESSION['cart']=[];header('Location: payment.php?id='.$oid);exit;}catch(Throwable $e){$pdo->rollBack();throw $e;}}?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>Shipping details</h1><form method="post"><label>Recipient name</label><input name="shipping_name" required><label>Phone</label><input name="phone" required><label>Address</label><textarea name="address" required></textarea><label>City</label><input name="city" required><label>Postal code</label><input name="postal_code" required><label>Delivery instructions</label><input name="delivery_note"><button>Continue to payment</button></form></div></div></body></html>